test_suite:
test('sets document.title on mount', () => {
  renderHook(() => useDocumentTitle('Hello'));
  expect(document.title).toBe('Hello');
});

test('updates document.title when title changes', () => {
  const { rerender } = renderHook(({ t }) => useDocumentTitle(t), { initialProps: { t: 'First' } });
  rerender({ t: 'Second' });
  expect(document.title).toBe('Second');
});

test('does not update if title is unchanged', () => {
  let calls = 0;
  Object.defineProperty(document, 'title', {
    get: () => 'Same',
    set: () => { calls++; },
    configurable: true
  });
  try {
    const { rerender } = renderHook(({ t }) => useDocumentTitle(t), { initialProps: { t: 'Same' } });
    const afterMount = calls;
    rerender({ t: 'Same' });
    expect(calls).toBe(afterMount);
  } finally {
    delete (document as any).title;
  }
});

